  'chart.pct.week1': 'Woche 1', 'chart.pct.week2': 'Woche 2', 'chart.pct.week3': 'Woche 3', 'chart.pct.deload': 'Deload',
  'chart.pct.title': 'Wendler 5/3/1 · 1RM 100 kg · Werte in kg über den Balken',
  'chart.pct.aria': '5/3/1-Zyklus: Prozent vom 1RM je Satz und Woche',
  'chart.linear.title': 'Kniebeuge · 5 × 5 · +2,5 kg (Unterkörper)',
