  'priv.toc.1': '1. Administrator', 'priv.toc.2': '2. Dane treningowe', 'priv.toc.3': '3. Powiadomienia',
  'priv.toc.4': '4. Zakupy i subskrypcje', 'priv.toc.5': '5. Dane zbierane przez Google Play', 'priv.toc.6': '6. Podstawy prawne',
