  'set.g2.h': 'Pihenők',
  'set.g2.li1': '<b>1. pihenő</b> az első emlékeztetőig: 60 mp', 'set.g2.li2': '<b>2. pihenő</b> a második emlékeztetőig: további 60 mp',
  'set.g2.li3': '<b>Gyakorlatok között:</b> 180 mp', 'set.g2.li4': 'Gyakorlatonként felülírható tervben és edzésben',
  'set.g3.h': 'Automatizált edzés',
  'set.g3.li1': 'Külön a bemelegítő és munkaszettekhez: az utolsó szett után <b>azonnal</b>, <b>megerősítés után</b> vagy <b>soha</b> ne lépjen tovább',
  'set.g3.li2': 'A befejezett edzések mindig, megerősítés után vagy soha ne legyenek újra hozzáfűzve',
