  'set.g4.li1': 'Dupla progresszió: 8–10 ism., mód választható', 'set.g4.li2': 'Ismétléscél: 25 ism. összesen',
  'set.g4.li3': 'Hullám progresszió: 8 → 6 ism., −1 edzésenként', 'set.g4.li4': 'Egy gyakorlat első átállításakor kerül átvételre, utána gyakorlatonként szerkeszthető',
  'set.g5.h': 'Felszerelés és test',
  'set.g5.li1': '<b>Súlyzók</b> névvel, súllyal és átmérővel', 'set.g5.li2': '<b>Tárcsák</b> darabszámmal, súllyal és átmérővel – ez a súlytárcsa-kalkulátor alapja',
  'set.g5.li3': 'Testsúly bejegyzések dátummal és idővel', 'set.g5.li4': 'Születési dátum → életkor és maximális pulzusszám',
  'set.g6.h': 'Adatok',
  'set.g6.li1': 'Minden adat helyben marad az eszközödön', 'set.g6.li2': 'Adatbázis mentése és visszaállítása fájlként',
  'set.g6.li3': 'Mentés Google Drive-on keresztül',
  'set.zones.h': 'Kardió edzészónák',
  'set.zones.p': 'A születési dátum alapján a CoCo kiszámolja a maximális pulzusodat életkor szerint, és öt edzészónát mutat hozzá – százalékban és konkrét percenkénti ütésszámban. Praktikus kardióhoz erőedzés előtt vagy után.',
  'set.zones.caption': 'Példa: 35 éves, HRmax 181–185 ü/perc',
