  'priv.meta.date': 'Sidst opdateret: 13. september 2026',
  'priv.meta.app': 'Gælder for Android-appen "Concept Coach" (CoCo)',
  'priv.summary.h': 'Kort opsummering',
  'priv.summary.li1': 'Dine træningsdata (planer, sessioner, sæt, udstyr) forbliver <strong>udelukkende på din enhed</strong> – der findes ingen brugerkonto og ingen cloud-synkronisering.',
  'priv.summary.li2': 'Vi anvender <strong>ingen reklamer</strong> og <strong>ingen analyse-/trackingtjenester</strong>.',
