  'prog.linear.h': 'Linear Progression',
  'prog.linear.p': 'Standarden for hver ny øvelse. Hvert arbeidssett har sitt eget mål. <strong>Alle mål nådd</strong> → én økning til neste gang. <strong>Ett bommet</strong> → samme vekt, ett nytt forsøk.',
  'prog.linear.dt1': 'Økning',
  'prog.linear.dd1': '2.5 kg underkropp, 1 kg overkropp – eller din egen verdi, absolutt eller i %',
