  'prog.double.h': 'Double Progression',
  'prog.double.p': 'Reps først, så vekt. Du jobber deg oppover innenfor et intervall; når <strong>hvert sett har nådd øvre grense</strong>, går vekten opp og alt begynner på nytt fra bunnen.',
  'prog.double.dt1': 'Intervall',
  'prog.double.dd1': 'standard 8–10 reps (1–100 hver)',
  'prog.double.dt2': 'Modus',
  'prog.double.dd2': '"+1 rep per sett hver økt" eller "+1 rep totalt" – da avanserer ett sett om gangen: 8·8·8 → 9·8·8 → 9·9·8 …',
  'prog.double.dt3': 'Bommet',
  'prog.double.dd3': 'samme mål på nytt',
  'prog.repgoal.h': 'Rep Goal System',
  'prog.repgoal.p': 'Du presser hvert arbeidssett nær utmattelse, og CoCo legger sammen repsene. <strong>Hvis totalen er over målet</strong>, får du mer vekt neste gang – å nå målet nøyaktig er ikke nok.',
  'prog.repgoal.dt1': 'Mål',
  'prog.repgoal.dd1': 'standard 25 reps totalt (1–100)',
  'prog.repgoal.dt2': 'Sett',
