  'prog.wave.dd3': 'samme mål på nytt',
  'prog.gzcl.h': 'GZCL Tiers',
  'prog.gzcl.p': 'Automatikken bak GZCLP. Hver øvelse har en rolle – <strong>T1</strong> hovedløft, <strong>T2</strong> sekundærløft, <strong>T3</strong> ekstra volum – og et stadium. Suksess betyr mer vekt; to mislykkede forsøk på rad betyr: neste stadium, færre men tyngre reps.',
  'prog.gzcl.dt1': 'T1',
  'prog.gzcl.dd1': '5 × 3+ → 6 × 2+ → 10 × 1+ · suksess vurderes ut fra AMRAP-settet',
  'prog.gzcl.dt2': 'T2',
  'prog.gzcl.dd2': '3 × 10 → 3 × 8 → 3 × 6 · hvert sett må lande',
  'prog.gzcl.dt3': 'T3',
  'prog.gzcl.dd3': '3 × 15+',
  'prog.gzcl.dt4': 'Etter stadium 3',
  'prog.gzcl.dd4': 'start på nytt med en −10% deload',
  'prog.percent.h': 'Prosentbasert (%1RM)',
  'prog.percent.p': 'For 5/3/1, nSuns, HST &amp; co. Hver uke i syklusen har sine egne sett med en <strong>prosentandel av din 1RM</strong>, reps og en AMRAP-markør. CoCo beregner vektene live fra din nåværende 1RM og runder av til lastbare 2.5 kg (eller 5 lbs) trinn.',
  'prog.percent.dt1': '1RM',
  'prog.percent.dd1': 'automatisk estimert, eller sett din egen faste verdi',
  'prog.percent.dt2': 'Syklus',
  'prog.percent.dd2': 'så mange uker du vil; den starter på nytt etter den siste',
  'prog.percent.dt3': 'Fremgang',
  'prog.percent.dd3': 'etter hvert som din 1RM stiger, stiger alle prosentvekter med den',
  'prog.net1.h': 'Auto-Deload',
  'prog.net1.p': 'Sikkerhetsnettet for hver vektbasert øvelse: etter et fastsatt antall mislykkede økter på rad, senkes vekten med et fast beløp eller en fast prosentandel. Bare arbeidssett telles. CoCo flagger uvanlig store reduksjoner.',
  'prog.net2.h': 'Tre øvelsestyper',
  'prog.net2.p': '<b>Vektbasert</b> med en av progresjonsordningene, <b>prosentbasert</b> med en ukentlig syklus, <b>tidsbasert</b> med sekunder og nedtelling. Typen låses etter det første fullførte settet.',
  'prog.net3.h': 'Egendefinerte økninger',
  'prog.net3.p': 'Økningen gjelder per øvelse – absolutt i kg/lbs eller som en prosentandel. Uten en egendefinert verdi bruker CoCo 2.5 kg for underkroppsøvelser og 1 kg for overkroppsøvelser.',
  'plans.where': 'I appen: Treningsplaner',
  'plans.title': 'Tolv innebygde planer',
  'plans.intro': 'De mest kjente programmene innen styrkeidrett, klare til bruk. Hver plan har en infovisning med en beskrivelse og et fullstendig beregnet progresjonseksempel. Fra en plan genererer CoCo hver økt i en syklus i ett jafs – navngitt etter uke og dag, f.eks. <span class="k">W1T2</span>.',
  'plans.th.plan': 'Plan',
