  'plans.how.man': 'manuell',
  'plans.r1.struct': '4-ukers syklus med tre oppbyggingsuker og en deload; knebøy, benkpress, markløft, skulderpress – én økt per løft.',
  'plans.r2.struct': '2 dager for over-/underkropp: 5/3/1-bølge pluss 3 × 10 på 65% (hoppes over i deload-uker), pluss tilbehørsøvelser på 3 × 10–20.',
  'plans.r3.struct': '4 dager: hovedløftet pluss nøyaktig to tilbehørsøvelser på 5 × 10 hver.',
  'plans.r4.struct': '4 dager, kun hovedløft – for perioder med lite tid eller mye stress.',
  'plans.r5.struct': 'Mer volum: 9 sett per løft etter prosent av treningsmaks, avsluttet med et AMRAP-toppsett.',
  'plans.r6.struct': '4 dager vekslende A1 – B1 – A2 – B2: T1 på 5 × 3+, T2 på 3 × 10, nedtrekk som T3 på 3 × 15.',
  'plans.r7.struct': 'Knebøy, benkpress, skulderpress, roing på 5 × 5, markløft på 1 × 5.',
  'plans.r8.struct': '3× per uke: 2 × 5 pluss et AMRAP-sett på knebøy, benkpress, pull-ups, skulderpress; markløft 1 × 5.',
  'plans.r9.struct': 'Ukentlig bølge for viderekomne: volumdag (5 × 5), lett restitusjonsdag, intensitetsdag (1 × 5 tungt).',
  'plans.r10.struct': 'High Intensity Training: ett sett til muskelsvikt per øvelse, korte og sjeldne økter.',
  'plans.r11.struct': 'Hypertrofispesifikk: faser med 15, 10 og 5 reps, 2 sett hver.',
  'plans.r12.struct': '10 × 10 per hovedøvelse i en 3-dagers splitt; vekten øker når alle ti sett lander.',
  'plans.foot1.h': 'Kopiere innebygde planer',
  'plans.foot1.li1': 'Innebygde planer er skrivebeskyttet. Å trykke på "Kopier plan" oppretter din redigerbare versjon.',
  'plans.foot1.li2': '"Manuell" betyr at den opprinnelige planen ikke foreskriver noen automatikk. I kopien setter du f.&nbsp;eks. <b>Linear Progression med et mål på 5</b> per øvelse – fra da av gjør CoCo matematikken.',
  'plans.foot1.li3': 'En dialog spør om startvekter før øktene genereres.',
  'plans.foot2.h': 'Bygge egne planer',
  'plans.foot2.li1': 'Sett sammen en plan av et hvilket som helst antall <b>treningsøkter</b>, hver med sitt eget øvelsesutvalg – eller som daggrupper som "Overkropp / Underkropp".',
  'plans.foot2.li2': 'Tre faner per øvelse: <b>Sett</b> (oppvarmings-, arbeids- og nedtrappingssett med reps og vekt), <b>Progresjon</b>, <b>Deload</b>.',
  'plans.foot2.li3': 'En øvelses oppvarmings- og nedtrappingsrampe brukes automatisk – kan slås av per øvelse.',
  'plans.foot2.li4': 'Hviletider per øvelse, planbeskrivelse på opptil 1,000 tegn.',
  'plans.foot2.li5': 'Gratis for opptil 2 egne planer, ubegrenset med Pro.',
