  'ex.title': 'Øvelser med struktur',
  'ex.intro': '57 øvelser er innebygd – fra knebøy og markløft til face pulls og nakkearbeid, pluss 14 generelle oppvarmingsøvelser og 12 tøyeøvelser. Hver av dem kan tilpasses, og du kan legge til dine egne.',
  'ex.g1.h': 'Klassifisering',
  'ex.g1.li1': '<b>Kroppsregion</b> over- eller underkropp – setter standardøkningen på 1 kg eller 2.5 kg.',
  'ex.g1.li2': '<b>Utstyr:</b> vektstang, hantel, maskin eller kroppsvekt.',
  'ex.g1.li3pre': '<b>Muskelgruppe</b> fra tolv kategorier:',
  'ex.muscles': ['Bryst', 'Rygg', 'Skuldre', 'Biceps', 'Triceps', 'Underarmer', 'Mage', 'Sete', 'Forlår', 'Baklår', 'Legger', 'Nakke'],
