  'priv.title': 'Personvernerklæring',
  'priv.meta.date': 'Sist oppdatert: 13. september 2026',
  'priv.meta.app': 'Gjelder Android-appen "Concept Coach" (CoCo)',
  'priv.summary.h': 'Kort oppsummering',
  'priv.summary.li1': 'Treningsdataene dine (planer, økter, sett, utstyr) forblir <strong>utelukkende på din enhet</strong> – det finnes ingen brukerkonto og ingen skysynkronisering.',
  'priv.summary.li2': 'Vi inkluderer <strong>ingen reklame</strong> og <strong>ingen analyse-/sporingstjenester</strong>.',
  'priv.summary.li3': 'Gongen fra hviletimeren bruker lokale varsler – ingenting forlater enheten din for dette.',
