  'priv.title': 'Tietosuojakäytäntö',
  'priv.meta.date': 'Viimeksi päivitetty: 13. syyskuuta 2026',
  'priv.meta.app': 'Koskee Android-sovellusta "Concept Coach" (CoCo)',
  'priv.summary.h': 'Tiivistelmä',
  'priv.summary.li1': 'Harjoitusdatasi (ohjelmat, harjoitukset, sarjat, varusteet) pysyy <strong>yksinomaan laitteellasi</strong> – käyttäjätiliä tai pilvisynkronointia ei ole.',
  'priv.summary.li2': 'Emme sisällytä <strong>mainontaa</strong> emmekä <strong>analytiikka-/seurantapalveluita</strong>.',
  'priv.summary.li3': 'Lepoajastimen gong käyttää paikallisia ilmoituksia – mitään ei lähetetä laitteeltasi tätä varten.',
  'priv.summary.li4': 'Vain <strong>Pro-oston/tilauksen</strong> yhteydessä ostodataa käsitellään RevenueCatin ja Google Playn kautta.',
  'priv.toc.label': 'Sisältö',
